/// <summary>
/// Receive lot ID
/// </summary>
/// <param name = "_inventTransIdReceive">Set receive lot ID</param>
/// <returns>Get receive lot ID</returns>
[DataMemberAttribute('InventTransIdReceive')]
public str parmInventTransIdReceive(str _inventTransIdReceive = inventTransIdReceive)
{
    if (!prmIsDefault(_inventTransIdReceive))
    {
        inventTransIdReceive = _inventTransIdReceive;
    }
    return inventTransIdReceive;
}

/// <summary>
/// Receive now quantity
/// </summary>
/// <param name = "_inventTransferQtyReceived">Set receive now quantity</param>
/// <returns>Get receive now quantity</returns>
[DataMemberAttribute('QtyReceiveNow')]
public real parmInventTransferQtyReceived(real _inventTransferQtyReceived = inventTransferQtyReceived)
{
    if (!prmIsDefault(_inventTransferQtyReceived))
    {
        inventTransferQtyReceived = _inventTransferQtyReceived;
    }
    return inventTransferQtyReceived;
}

/// <summary>
/// CW receive now quantity
